def sum_to(n):
    # add up 1, 2, ..., n with a loop
    pass

exercises.solution:
def sum_to(n):
    total = 0
    for i in range(1, n + 1):
        total += i
    return total

exercises.starter:
def factorial(n):
    # multiply together 1, 2, ..., n
    pass

exercises.solution:
def factorial(n):
    product = 1
    for i in range(2, n + 1):
        product *= i
    return product

