def count_matching(xs, target):
    # count how many elements equal target
    pass

exercises.solution:
def count_matching(xs, target):
    count = 0
    for x in xs:
        if x == target:
            count += 1
    return count

exercises.starter:
def first_index_of(xs, target):
    # return the index of the first match, or -1
    pass

exercises.solution:
def first_index_of(xs, target):
    for i, x in enumerate(xs):
        if x == target:
            return i
    return -1

exercises.starter:
def collatz_steps(n):
    # count steps to reach 1
    pass

exercises.solution:
def collatz_steps(n):
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps
